`timescale 1ns / 1ps
`include "params.vh"
`include "data_dir.vh"   // defines DATA_DIR: absolute path to rtl/ on THIS machine.
                         // Generated by scripts/create_project.tcl (not committed).
// ============================================================================
// tb_layer2.v -- self-checking testbench for layer2.v
//
// Tests layer 2 in isolation: the hidden values come straight from the
// "hq" lines of golden.txt, not from layer1.v, so a layer-2 bug can't hide
// behind (or be blamed on) layer 1.
//
//   GOLDEN     64 images: all 10 scores vs the "acc2" lines of golden.txt
//   SYNTHETIC  real hidden values are small (max 69) and many are 0, so three
//              made-up inputs cover the rest: ramp (every input nonzero and
//              distinct), all127 (maximum input), hot (127 wherever the
//              highest-scoring class has a positive weight). Expected values
//              come from w2.mem (class-major), not the w2_t.mem the hardware
//              reads, so a packing error is caught too.
//   CONTROL    latency exactly 34 cycles, single done pulse, busy correct,
//              stray start mid-run ignored
// ============================================================================

module tb_layer2;

    localparam N_IN    = `N_HIDDEN;
    localparam N_O     = `N_OUT;
    localparam ACC_W   = `ACC_W;
    localparam N_IMG   = 64;
    localparam N_SYN   = 3;
    localparam LATENCY = 34;

    reg                     clk = 0, rst = 1, start = 0;
    reg  [N_IN*8-1:0]       h = 0;
    wire                    busy, done;
    wire [N_O*ACC_W-1:0]    scores;

    layer2 dut (
        .clk(clk), .rst(rst), .start(start), .busy(busy), .done(done),
        .h_flat(h), .scores_flat(scores)
    );

    always #5 clk = ~clk;

    integer n_pass = 0, f_gold = 0, f_syn = 0, f_ctl = 0;
    integer t, n, j, s, gv, rc, fd, got, sum, lat, extra, busy_drops, best_n, best_sum;
    integer g_acc2 [0:N_O-1];
    reg [8*16-1:0] tok;
    reg [7:0]  w2 [0:N_O*N_IN-1];       // class-major, independent of w2_t.mem
    reg [31:0] b2 [0:N_O-1];

    task run(input integer stray, input integer id);
        begin
            busy_drops = 0;
            start = 1; @(posedge clk); #1; start = 0;
            lat = 0;
            while (!done && lat < 500) begin
                if (!busy) busy_drops = busy_drops + 1;
                if (stray && lat == 10) start = 1;
                @(posedge clk); #1;
                start = 0;
                lat = lat + 1;
            end
            if (busy) busy_drops = busy_drops + 1;
            extra = 0;
            repeat (3) begin @(posedge clk); #1; if (done || busy) extra = extra + 1; end
            if (lat != LATENCY || extra != 0 || busy_drops != 0) begin
                f_ctl = f_ctl + 1;
                $display("FAIL  run %0d control: latency=%0d (want %0d) extra=%0d busy_drops=%0d",
                         id, lat, LATENCY, extra, busy_drops);
            end
        end
    endtask

    initial begin
        $display("==== tb_layer2 ====");
        $readmemh({`DATA_DIR, "w2.mem"}, w2);
        $readmemh({`DATA_DIR, "b2.mem"}, b2);
        fd = $fopen({`DATA_DIR, "golden.txt"}, "r");
        if (fd == 0) begin
            $display("FAIL  could not open golden.txt -- check DATA_DIR");
            $finish;
        end
        rc = $fscanf(fd, "%s", tok);
        while (tok != "img") rc = $fscanf(fd, "%s", tok);

        repeat (3) @(posedge clk);
        #1 rst = 0;
        @(posedge clk); #1;

        // ================================================= GOLDEN
        for (t = 0; t < N_IMG; t = t + 1) begin
            rc = $fscanf(fd, "%d %s %d %s %d", gv, tok, gv, tok, gv);
            rc = $fscanf(fd, "%s", tok);                                    // acc1
            for (j = 0; j < N_IN; j = j + 1) rc = $fscanf(fd, "%d", gv);
            rc = $fscanf(fd, "%s", tok);                                    // hq -> input
            for (j = 0; j < N_IN; j = j + 1) begin
                rc = $fscanf(fd, "%d", gv);
                h[8*j +: 8] = gv;
            end
            rc = $fscanf(fd, "%s", tok);                                    // acc2 -> expected
            for (n = 0; n < N_O; n = n + 1) rc = $fscanf(fd, "%d", g_acc2[n]);
            rc = $fscanf(fd, "%s", tok);                                    // next img

            run(t == 0, t);
            for (n = 0; n < N_O; n = n + 1) begin
                got = $signed(scores[ACC_W*n +: ACC_W]);
                if (got !== g_acc2[n]) begin
                    f_gold = f_gold + 1;
                    if (f_gold <= 10)
                        $display("FAIL  img %0d class %0d: expected %0d, got %0d", t, n, g_acc2[n], got);
                end else n_pass = n_pass + 1;
            end
        end
        $fclose(fd);

        // ================================================= SYNTHETIC
        // strongest class = largest bias + 127 * (sum of its positive weights)
        best_n = 0; best_sum = -2147483647;
        for (n = 0; n < N_O; n = n + 1) begin
            sum = $signed(b2[n]);
            for (j = 0; j < N_IN; j = j + 1)
                if ($signed(w2[n*N_IN + j]) > 0) sum = sum + 127 * $signed(w2[n*N_IN + j]);
            if (sum > best_sum) begin best_sum = sum; best_n = n; end
        end

        for (s = 0; s < N_SYN; s = s + 1) begin
            for (j = 0; j < N_IN; j = j + 1)
                case (s)
                    0: h[8*j +: 8] = 4*j + 3;                                       // ramp 3..127
                    1: h[8*j +: 8] = 127;                                           // all127
                    2: h[8*j +: 8] = ($signed(w2[best_n*N_IN + j]) > 0) ? 127 : 0;  // hot
                endcase
            run(0, 100 + s);
            for (n = 0; n < N_O; n = n + 1) begin
                sum = $signed(b2[n]);
                for (j = 0; j < N_IN; j = j + 1)
                    sum = sum + $signed({1'b0, h[8*j +: 8]}) * $signed(w2[n*N_IN + j]);
                got = $signed(scores[ACC_W*n +: ACC_W]);
                if (got !== sum) begin
                    f_syn = f_syn + 1;
                    if (f_syn <= 10)
                        $display("FAIL  synthetic %0d class %0d: expected %0d, got %0d", s, n, sum, got);
                end else n_pass = n_pass + 1;
            end
        end

        $display("golden   : %0d images x %0d classes, %0d fail", N_IMG, N_O, f_gold);
        $display("synthetic: %0d inputs x %0d classes, %0d fail", N_SYN, N_O, f_syn);
        $display("control  : %0d runs, %0d fail  (latency %0d cycles = %0d ns)",
                 N_IMG + N_SYN, f_ctl, LATENCY, LATENCY * 10);
        $display("================================");
        if (f_gold + f_syn + f_ctl == 0)
            $display("ALL TESTS PASSED  (%0d checks)", n_pass + N_IMG + N_SYN);
        else
            $display("%0d CHECKS FAILED", f_gold + f_syn + f_ctl);
        $display("================================");
        $finish;
    end

endmodule
